import hashlib,json,zipfile
def strict_object(pairs):
    obj={}
    for key,value in pairs:
        if key in obj: raise ValueError("duplicate JSON key: "+key)
        obj[key]=value
    return obj
def reject_constant(value): raise ValueError("non-finite JSON constant: "+value)
def loads(raw): return json.loads(raw,object_pairs_hook=strict_object,parse_constant=reject_constant)
